function.arguments:
{"command":"awk -F',' 'NR>1 {
  rows++;
  units += $5;
  revenue += $5 * $6;
  cat_rev[$4] += $5 * $6;
}
END {
  printf "row_count: %d\n", rows;
  printf "total_units: %d\n", units;
  printf "total_revenue: %.2f\n", revenue;
  for (cat in cat_rev) {
    printf "  %s: %.2f\n", cat, cat_rev[cat];
  }
}' data/sales.csv"}
